mapper.select:
SELECT id, workspace_id, knowledge_base_id, goal, status, agent_key, agent_version,
	prompt_id, prompt_version, model_provider, model_name, configuration::text AS configuration,
	next_step_sequence, deadline_at, cancel_requested_at, lease_owner, lease_expires_at,
	error_code, error_message, final_answer, created_at, started_at, completed_at, updated_at
FROM agent_runs WHERE workspace_id = #{workspaceId}
AND knowledge_base_id = #{knowledgeBaseId} AND id = #{runId}
